import mongoose from "mongoose";

export interface IChatRoom {
  _id?: mongoose.Types.ObjectId;

  type: "user-vendor" | "vendor-admin";

  user?: mongoose.Types.ObjectId;
  vendor?: mongoose.Types.ObjectId;
  admin?: mongoose.Types.ObjectId;

  product?: mongoose.Types.ObjectId; // user-vendor chat ke liye

  lastMessage?: string;
}

const chatRoomSchema = new mongoose.Schema<IChatRoom>(
  {
    type: {
      type: String,
      enum: ["user-vendor", "vendor-admin"],
      required: true,
    },

    user: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
    },

    vendor: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
    },

    admin: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
    },

    product: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Product",
    },

    lastMessage: String,
  },
  { timestamps: true }
);

export default mongoose.models.ChatRoom ||
  mongoose.model<IChatRoom>("ChatRoom", chatRoomSchema);
