import { auth } from "@/auth";
import connectDb from "@/lib/db";
import ChatRoom from "@/models/chatRoom.model";
import { NextResponse } from "next/server";

export async function GET() {
  await connectDb();
  const session = await auth();

  if (!session?.user?.id) {
    return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
  }

  const userId = session.user.id;
  const role = session.user.role;

  let rooms = [];

  if (role === "user") {
    rooms = await ChatRoom.find({ user: userId })
      .populate("vendor", "name image shopName")
      .populate("product", "title image1");
  }

  if (role === "vendor") {
    rooms = await ChatRoom.find({ vendor: userId })
      .populate("user", "name image")
      .populate("product", "title image1")
      .populate("admin", "name image");
  }

  if (role === "admin") {
    rooms = await ChatRoom.find({ type: "vendor-admin" })
      .populate("vendor", "name image shopName");
  }

  return NextResponse.json(rooms);
}
